class Solution {
public:
    int findMaxConsecutiveOnes(vector<int>& nums) {
        int maxCnt = 0, curCnt = 0;
        for (int x : nums) {
            if (x == 1) {
                curCnt++;
                if (curCnt > maxCnt) maxCnt = curCnt;
            } else {
                curCnt = 0;
            }
        }
        return maxCnt;
    }
};

