var findMaxConsecutiveOnes = function(nums) {
    let maxCnt = 0, curCnt = 0;
    for (const x of nums) {
        if (x === 1) {
            curCnt++;
            if (curCnt > maxCnt) maxCnt = curCnt;
        } else {
            curCnt = 0;
        }
    }
    return maxCnt;
};
